targets.source:
(
  100 * (
    max by(ip, bk_target_cloud_id, instance_role) (
        bkmonitor:dbm_system:net:speed_packets_recv{shard=~"$shard",
          cluster_domain="$cluster_domain",
          device_name="eth1",
          instance_role=~"$instance_role"
        }

    ) +
    max by(ip, bk_target_cloud_id, instance_role) (
        bkmonitor:dbm_system:net:speed_packets_sent{shard=~"$shard",
          cluster_domain="$cluster_domain",
          device_name="eth1",
          instance_role=~"$instance_role"
        }

    )
  ) /  (96 * 1024 * 1024)  /
  sum by(ip, bk_target_cloud_id, instance_role) (
       bkmonitor:dbm_system:cpu_detail:usage{shard=~"$shard",
        cluster_domain="$cluster_domain",
        instance_role=~"$instance_role"
      }
  )   and
    sum by(ip, bk_target_cloud_id, instance_role) (
        bkmonitor:dbm_system:cpu_detail:usage{shard=~"$shard",
          cluster_domain="$cluster_domain",
          instance_role=~"$instance_role"
        }
    ) <= 2
   or
  (
    100 * (
      max by(ip, bk_target_cloud_id, instance_role) (
          bkmonitor:dbm_system:net:speed_packets_recv{shard=~"$shard",
            cluster_domain="$cluster_domain",
            device_name="eth1",
            instance_role=~"$instance_role"
          }
      ) +
      max by(ip, bk_target_cloud_id, instance_role) (
          bkmonitor:dbm_system:net:speed_packets_sent{shard=~"$shard",
            cluster_domain="$cluster_domain",
            device_name="eth1",
            instance_role=~"$instance_role"
          }
      )
    ) / (48 * 1024 * 1024)/
    sum by(ip, bk_target_cloud_id, instance_role) (
         bkmonitor:dbm_system:cpu_detail:usage{shard=~"$shard",
          cluster_domain="$cluster_domain",
          instance_role=~"$instance_role"
        }
    )  and

    sum by(ip, bk_target_cloud_id, instance_role) (
        bkmonitor:dbm_system:cpu_detail:usage{shard=~"$shard",
          cluster_domain="$cluster_domain",
          instance_role=~"$instance_role"
        }
    ) > 2
  )
)

max(
  100 *
  max by (instance, instance_role) (
    custom:dbm_report_channel:mongo_datadir_disk_used_kb{shard=~"$shard",cluster_domain="$cluster_domain",instance_role=~"$instance_role",instance_role!="backup"}
  )
  /
  max by (instance, instance_role) (
    custom:dbm_report_channel:mongo_datadir_disk_total_kb{shard=~"$shard",cluster_domain="$cluster_domain",instance_role=~"$instance_role",instance_role!="backup"}
  )
)

label_replace(
    label_replace(
        (
            max by (instance_role, instance, rs_state) (bkmonitor:exporter_dbm_mongodb_exporter:mongodb_ss_mem_virtual{shard=~"$shard",cluster_domain="$cluster_domain",instance_role=~"$instance_role"})
        ),
        "rs_state", "SEC", "rs_state", "2"
    ),
    "rs_state", "PRI", "rs_state", "1"
)

100 *
max by (instance, instance_role) (
  custom:dbm_report_channel:mongo_datadir_disk_used_kb{shard=~"$shard",cluster_domain="$cluster_domain",instance_role=~"$instance_role"}
)
/
max by (instance, instance_role) (
  custom:dbm_report_channel:mongo_datadir_disk_total_kb{shard=~"$shard",cluster_domain="$cluster_domain",instance_role=~"$instance_role"}
)

label_replace(
    label_replace(
        (
            max by (instance_role, instance, type, rs_state) (bkmonitor:exporter_dbm_mongodb_exporter:mongodb_mongod_global_lock_current_queue{shard=~"$shard",cluster_domain="$cluster_domain",instance_role=~"$instance_role",type!="total"})
        ),
        "rs_state", "SEC", "rs_state", "2"
    ),
    "rs_state", "PRI", "rs_state", "1"
)

label_replace(
    label_replace(
        (
            max by (instance_role, instance, rs_state) (bkmonitor:exporter_dbm_mongodb_exporter:mongodb_mongod_wiredtiger_session_open_sessions_total{shard=~"$shard",cluster_domain="$cluster_domain",instance_role=~"$instance_role",type!="total"})
        ),
        "rs_state", "SEC", "rs_state", "2"
    ),
    "rs_state", "PRI", "rs_state", "1"
)
